callback_with_context.context_function_id:
(
  max_marks_effect = PlayersFaction.PooledResourceContext("wh3_dlc29_glott_souls").CurrentGroupPooledResourceEffectContext("ABSOLUTE_VALUE").EffectBundle.EffectList.FirstContext(EffectKey == "wh3_dlc29_effect_glottkin_nurgle_marks_max_capacity_dummy"),
  max_marks = GetIfElse(IsContextValid(max_marks_effect), max_marks_effect.Value, 0),
  can_afford = PlayersFaction.PooledResourceManagerContext.CanAffordResourceCost(this),
  marks_purchased = Clamp(0, RoundFloat(SharedStateReadFloat("glottkin_amount_of_purchased_marks")), 999)
)
=>
{
  GetIfElse(can_afford && marks_purchased < max_marks, "active", "inactive")
}

(
  characters_list = Component("characters", "^1"),
  settlements_list = Component("settlements", "^1")
)
=>
{
  (characters_list.IsVisible && characters_list.NumChildren <= 1)
    || (settlements_list.IsVisible && settlements_list.NumChildren <= 1)
}

(
  shared_state_key = Key.Substr(0, Key.Length - "_level_0".Length) + "_requirement",
  requirements_string = SharedStateReadString(shared_state_key)
) => {
  requirements_string.Split(";")
}

(
  max_marks_effect = PlayersFaction.PooledResourceContext("wh3_dlc29_glott_souls").CurrentGroupPooledResourceEffectContext("ABSOLUTE_VALUE").EffectBundle.EffectList.FirstContext(EffectKey == "wh3_dlc29_effect_glottkin_nurgle_marks_max_capacity_dummy"),
  max_marks = GetIfElse(IsContextValid(max_marks_effect), max_marks_effect.Value, 0),
  marks_purchased = Clamp(0, RoundFloat(SharedStateReadFloat("glottkin_amount_of_purchased_marks")), 999)
)
=>
{
  SharedStateReadBool(init.Key + "_purchased") == false && marks_purchased >= max_marks || init.ExMarksOfNurgle_IsOnCooldown
}

(
  splits = Split("-"),
  requirement_str = splits.At(0),
  requirement_val = RoundFloat(ToNumber(splits.At(1)))
) => {
  Format(requirement_str, requirement_val)
}
